// is not null: a member's own rename passes it, an admin's does not.
func (q *Queries) RenameUser(ctx context.Context, arg RenameUserParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, renameUser,
		arg.Handle,
		arg.ChangedAt,
		arg.UpdatedAt,
		arg.ID,
		arg.OldHandle,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setUserRole = `-- name: SetUserRole :exec
UPDATE users SET role = ?, updated_at = ? WHERE id = ?
`

type SetUserRoleParams struct {
	Role      string
	UpdatedAt int64
	ID        int64
}

func (q *Queries) SetUserRole(ctx context.Context, arg SetUserRoleParams) error {
	_, err := q.db.ExecContext(ctx, setUserRole, arg.Role, arg.UpdatedAt, arg.ID)
	return err
}

const setUserStatus = `-- name: SetUserStatus :exec
UPDATE users
SET status = ?, status_reason = ?, status_until = ?, status_version = status_version + 1, updated_at = ?
WHERE id = ?
`

type SetUserStatusParams struct {
	Status       string
	StatusReason string
	StatusUntil  sql.NullInt64
	UpdatedAt    int64
	ID           int64
}

// SetUserStatus is every status change but anonymizing (internal/perm,
// lifecycle.go). It writes the reason and end with the status, so a
// suspension's reason never outlives it, and counts the change in
// status_version.
func (q *Queries) SetUserStatus(ctx context.Context, arg SetUserStatusParams) error {
	_, err := q.db.ExecContext(ctx, setUserStatus,
		arg.Status,
		arg.StatusReason,
		arg.StatusUntil,
		arg.UpdatedAt,
		arg.ID,
	)
	return err
}

const sweepSessions = `-- name: SweepSessions :execrows
DELETE FROM sessions
WHERE expires_at <= ?1
   OR last_used_at <= ?2
`

type SweepSessionsParams struct {
	ExpiresAfter  int64
	LastUsedAfter int64
}

// SweepSessions deletes every session LookupSession would refuse: the exact
// complement of its liveness test. internal/auth/session binds both cutoffs
// from session.ExpiredBefore, so the sweeper deletes nothing a lookup at the
// same moment would still accept (TKT-01M29C5Y2S).
func (q *Queries) SweepSessions(ctx context.Context, arg SweepSessionsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, sweepSessions, arg.ExpiresAfter, arg.LastUsedAfter)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const touchSession = `-- name: TouchSession :execrows
UPDATE sessions SET last_used_at = ?1
WHERE id_hash = ?2
  AND last_used_at <= ?3
  AND expires_at > ?4
  AND last_used_at > ?5
`

type TouchSessionParams struct {
	Now           int64
	IDHash        sqltypes.SessionHash
	DueBefore     int64
	ExpiresAfter  int64
	LastUsedAfter int64
}

// TouchSession slides last_used_at only when the stored value is due, so the
// once-per-five-minutes rule holds in the statement itself: two requests that
// both read a due value write once between them. It also requires the row to
// be alive by the same cutoffs as LookupSession, at the time of the write, so
// a touch that lands just after the idle boundary cannot revive the session.
func (q *Queries) TouchSession(ctx context.Context, arg TouchSessionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, touchSession,
		arg.Now,
		arg.IDHash,
		arg.DueBefore,
		arg.ExpiresAfter,
		arg.LastUsedAfter,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateUserSettings = `-- name: UpdateUserSettings :one
UPDATE users
SET timezone = COALESCE(?1, timezone),
    prefs_json = json_patch(
        CASE WHEN json_valid(prefs_json)
             THEN CASE WHEN json_type(prefs_json) = 'object' THEN prefs_json ELSE '{}' END
             ELSE '{}' END,
        ?2),
    updated_at = ?3
WHERE id = ?4
RETURNING timezone, locale, prefs_json
`

type UpdateUserSettingsParams struct {
	Timezone  sql.NullString
	Prefs     interface{}
	UpdatedAt int64
	ID        int64
}

type UpdateUserSettingsRow struct {
	Timezone  sql.NullString
	Locale    sql.NullString
	PrefsJson string
}

// UpdateUserSettings writes a member's own settings in one statement
// (TKT-01M29CCC0X). timezone is kept when null. prefs is a JSON object of
// only the keys the request named, merged into prefs_json, so a key the
// request did not name is kept. A stored prefs_json that is not a JSON
// object starts again from '{}': the reader already treats it as no
// preferences, and json_patch would refuse it. The guard nests because
// SQLite does not promise to short-circuit AND and json_type raises on
// malformed JSON (Terva reviews 1704 and 1734).
func (q *Queries) UpdateUserSettings(ctx context.Context, arg UpdateUserSettingsParams) (UpdateUserSettingsRow, error) {
	row := q.db.QueryRowContext(ctx, updateUserSettings,
		arg.Timezone,
		arg.Prefs,
		arg.UpdatedAt,
		arg.ID,
	)
	var i UpdateUserSettingsRow
	err := row.Scan(&i.Timezone, &i.Locale, &i.PrefsJson)
	return i, err
}

const userIdentities = `-- name: UserIdentities :many
SELECT id, user_id, provider_key, subject, email, email_verified, issuer, last_login_at, raw_claims_json, created_at, updated_at, blocked_at, blocked_by FROM identities WHERE user_id = ? ORDER BY id
`

// UserIdentities is every identity an account has, oldest first: the
// settings screen's list, and what removing one counts (TKT-01M29CCC0X).
func (q *Queries) UserIdentities(ctx context.Context, userID sql.NullInt64) ([]Identity, error) {
	rows, err := q.db.QueryContext(ctx, userIdentities, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Identity
	for rows.Next() {
		var i Identity
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.ProviderKey,
			&i.Subject,
			&i.Email,
			&i.EmailVerified,
			&i.Issuer,
			&i.LastLoginAt,
			&i.RawClaimsJson,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.BlockedAt,
			&i.BlockedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usersByHandlePrefix = `-- name: UsersByHandlePrefix :many
SELECT handle, display_name, avatar_blob, role, kind FROM users
WHERE handle >= ?1 AND handle < ?2
  AND status = 'active'
  AND substr(handle, -1) <> '-'
ORDER BY handle
LIMIT ?3
`

type UsersByHandlePrefixParams struct {
	Lo  string
	Hi  string
	Lim int64
}

type UsersByHandlePrefixRow struct {
	Handle      string
	DisplayName string
	AvatarBlob  sql.NullString
	Role        string
	Kind        string
}

// Mention autocomplete (GET /api/v1/users?prefix=). lo is the prefix as
// typed and hi is lo with '{' appended, which sorts after every handle
// character. Both compare under the column's NOCASE collation, which folds
// the case, so this is a range search on the handle index. A handle ending in '-' is left out: the mention parser
// reads a trailing '-' as punctuation, so such a handle cannot be mentioned
// and suggesting it would insert a mention of somebody else.
func (q *Queries) UsersByHandlePrefix(ctx context.Context, arg UsersByHandlePrefixParams) ([]UsersByHandlePrefixRow, error) {
	rows, err := q.db.QueryContext(ctx, usersByHandlePrefix, arg.Lo, arg.Hi, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsersByHandlePrefixRow
	for rows.Next() {
		var i UsersByHandlePrefixRow
		if err := rows.Scan(
			&i.Handle,
			&i.DisplayName,
			&i.AvatarBlob,
			&i.Role,
			&i.Kind,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usersByIDs = `-- name: UsersByIDs :many
SELECT id, handle, display_name, avatar_blob, status, role, kind, bio_source, timezone, locale, prefs_json, mark_all_read_at, created_at, updated_at, last_seen_at, status_reason, status_until, status_version, anonymized, handle_changed_at FROM users WHERE id IN (/*SLICE:ids*/?) ORDER BY id
`

// The authors on one page of a thread, in one query rather than one per post.
func (q *Queries) UsersByIDs(ctx context.Context, ids []int64) ([]User, error) {
	query := usersByIDs
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []User
	for rows.Next() {
		var i User
		if err := rows.Scan(
			&i.ID,
			&i.Handle,
			&i.DisplayName,
			&i.AvatarBlob,
			&i.Status,
			&i.Role,
			&i.Kind,
			&i.BioSource,
			&i.Timezone,
			&i.Locale,
			&i.PrefsJson,
			&i.MarkAllReadAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.LastSeenAt,
			&i.StatusReason,
			&i.StatusUntil,
			&i.StatusVersion,
			&i.Anonymized,
			&i.HandleChangedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
